// See README.md for license details.
// -----------------------------------------------------------------------------
//  SimpleBackend.scala — NPU backend: InstrDecoder + MultiWidthRF + MMALU + VALU
//
//  Parameters:
//    K    — SIMD lane count per register = MMALU array side (default 8).
//           At the top level, K = 64 to match MMALU(new MMPE(), 64, 8, 32).
//    N    — base lane width in bits / N(bits) (default 8).
//    L    — number of VX base registers (default 32, must be div-by-4).
//
//  MMALU mapping: MMALU.n (array side) == K; MMALU.nbits == N.
//  This is the backend boundary alignment constraint. Both must be equal.
//
//  Register file (MultiWidthRegisterBlock):
//    VX[0..L-1]     K × N bits     INT8 / BF8 results, MMALU narrow inputs
//    VE[0..L/2-1]   K × 2N bits    INT16 / BF16 results
//    VR[0..L/4-1]   K × 4N bits    INT32 / FP32 results; MMALU accumulator direct write
//
//  Port assignments:
//    VX read:  port 0 = MMALU in_a; port 1 = VALU in_a_vx
//    VX read:  port 2 = VALU in_b_vx; port 3 = external read
//    VE read:  port 0 = VALU in_a_ve; port 1 = VALU in_b_ve
//    VR read:  port 0 = VALU in_a_vr + MMALU in_b; port 1 = VALU in_b_vr + in_c_vr
//    VX write: port 0 = VALU narrow out; port 1 = external write
//    VE write: port 0 = VALU VE out
//    VR write: port 0 = VALU VR out; port 1 = MMALU accumulator direct (INT32, no truncation)
//
//  Instruction decode: 32-bit word → InstrDecoder → DecodedMicroOp.
//  All dispatch is based on the decoded family + VecOp.
//
//  Write-back timing: VALU has a 1-cycle output register.
//  The backend keeps the decoded op active for 2 cycles (issue + write-back).
//  A production frontend should use a 1-cycle pipeline stall or forwarding.
// -----------------------------------------------------------------------------

package backend

import chisel3._
import chisel3.util._

import alu.mma._
import alu.pe._
import alu.vec._
import isa._
import isa.micro_op._
import sram.mwreg._

// Width constants matching VecWidth enum values (0=VX, 1=VE, 2=VR)
// Used to compare dec.valu.regCls (UInt(2.W)) without importing ChiselEnum
private object W { val VX = 0.U(2.W); val VE = 1.U(2.W); val VR = 2.U(2.W) }

class NCoreBackend(
    val K: Int = 8,
    val N: Int = 8,
    val L: Int = 32,
) extends Module {

  require(L % 4 == 0, s"NCoreBackend: L=$L must be divisible by 4")
  require(K > 0 && N > 0)

  val N2 = 2 * N
  val N4 = 4 * N

  val VX_ADDR = log2Ceil(L)
  val VE_ADDR = log2Ceil(L / 2)
  val VR_ADDR = log2Ceil(L / 4)

  val io = IO(new Bundle {
    // Raw 32-bit instruction word (from frontend or test harness)
    val instr       = Input(UInt(32.W))
    val illegal_out = Output(Bool())  // illegal instruction flag

    // ---- VX address ports (test harness / future frontend) ----
    val vx_a_addr   = Input(UInt(VX_ADDR.W))
    val vx_b_addr   = Input(UInt(VX_ADDR.W))
    val vx_out_addr = Input(UInt(VX_ADDR.W))

    // ---- VE address ports ----
    val ve_a_addr   = Input(UInt(VE_ADDR.W))
    val ve_b_addr   = Input(UInt(VE_ADDR.W))
    val ve_out_addr = Input(UInt(VE_ADDR.W))

    // ---- VR address ports (rd=output; rs1=A; rs2=B; rs3=C for FMA) ----
    val vr_a_addr   = Input(UInt(VR_ADDR.W))
    val vr_b_addr   = Input(UInt(VR_ADDR.W))
    val vr_c_addr   = Input(UInt(VR_ADDR.W))
    val vr_out_addr = Input(UInt(VR_ADDR.W))

    // ---- MMALU control passthrough ----
    val mma_a_addr   = Input(UInt(VX_ADDR.W))
    val mma_b_addr   = Input(UInt(VX_ADDR.W))
    val mma_out_addr = Input(UInt(VR_ADDR.W))  // MMALU output goes to VR

    // ---- External RF access (VX width) ----
    val ext_wr_en   = Input(Bool())
    val ext_wr_addr = Input(UInt(VX_ADDR.W))
    val ext_wr_data = Input(Vec(K, UInt(N.W)))
    val ext_rd_addr = Input(UInt(VX_ADDR.W))
    val ext_rd_data = Output(Vec(K, UInt(N.W)))

    // ---- External VR access (for reading INT32 / FP32 results) ----
    val vr_rd_addr  = Input(UInt(VR_ADDR.W))
    val vr_rd_data  = Output(Vec(K, UInt(N4.W)))
  })

  // ==========================================================================
  // Instruction decoder
  // ==========================================================================
  val decoder = Module(new InstrDecoder)
  decoder.io.instr := io.instr
  io.illegal_out   := decoder.io.illegal
  val dec = decoder.io.decoded

  // ==========================================================================
  // Multi-width register file
  // ==========================================================================
  val rf = Module(new MultiWidthRegisterBlock(L, K, N,
    vx_rd = 4, vx_wr = 2, ve_rd = 2, ve_wr = 1, vr_rd = 2, vr_wr = 2))

  // ---- VX reads ----
  rf.io.vx_r_addr(0) := io.mma_a_addr    // MMALU A
  rf.io.vx_r_addr(1) := io.vx_a_addr     // VALU in_a_vx
  rf.io.vx_r_addr(2) := io.vx_b_addr     // VALU in_b_vx
  rf.io.vx_r_addr(3) := io.ext_rd_addr   // external
  io.ext_rd_data      := rf.io.vx_r_data(3)

  // ---- VE reads ----
  rf.io.ve_r_addr(0) := io.ve_a_addr
  rf.io.ve_r_addr(1) := io.ve_b_addr

  // ---- VR reads ----
  rf.io.vr_r_addr(0) := io.vr_a_addr
  rf.io.vr_r_addr(1) := io.vr_b_addr
  io.vr_rd_data       := rf.io.vr_r_data(0)

  // Drive the external read port of the RF (separate from vx_r_addr)
  rf.io.ext_r_addr := io.ext_rd_addr

  // ---- Default: all write ports disabled ----
  rf.io.vx_w_en  := VecInit(Seq.fill(2)(false.B))
  rf.io.ve_w_en  := VecInit(Seq.fill(1)(false.B))
  rf.io.vr_w_en  := VecInit(Seq.fill(2)(false.B))
  rf.io.vx_w_addr := VecInit(Seq.fill(2)(0.U(VX_ADDR.W)))
  rf.io.ve_w_addr := VecInit(Seq.fill(1)(0.U(VE_ADDR.W)))
  rf.io.vr_w_addr := VecInit(Seq.fill(2)(0.U(VR_ADDR.W)))
  for (p <- 0 until 2) for (lane <- 0 until K) rf.io.vx_w_data(p)(lane) := 0.U
  for (p <- 0 until 1) for (lane <- 0 until K) rf.io.ve_w_data(p)(lane) := 0.U
  for (p <- 0 until 2) for (lane <- 0 until K) rf.io.vr_w_data(p)(lane) := 0.U

  // ---- External write ----
  rf.io.ext_w_en   := io.ext_wr_en
  rf.io.ext_w_addr := io.ext_wr_addr
  rf.io.ext_w_data := io.ext_wr_data

  // ==========================================================================
  // MMALU (systolic array; n = K lanes, nbits = N)
  // ==========================================================================
  val mmalu = Module(new MMALU(new MMPE(N), K, N, N4))
  mmalu.io.in_a := VecInit(rf.io.vx_r_data(0).map(_.asSInt))
  // MMALU in_b taken from VX (same layout as in_a, different addr)
  rf.io.vx_r_addr(0) := io.mma_a_addr  // already assigned above; in_b via separate VX port
  // Note: we route MMALU in_b through vx_r_data(0) with mma_b_addr
  // To give MMALU its own B port, we repurpose ext port when no ext read is active.
  // For simplicity in tests, use the same vx_r_data(3) for MMALU B (driven by mma_b_addr).
  rf.io.vx_r_addr(3) := Mux(io.ext_wr_en || io.ext_rd_addr.orR, io.ext_rd_addr, io.mma_b_addr)
  mmalu.io.in_b     := VecInit(rf.io.vx_r_data(3).map(_.asSInt))
  mmalu.io.in_accum := VecInit(Seq.fill(K)(0.S(N4.W)))

  // MMALU control from decoded instruction
  mmalu.io.ctrl.keep      := dec.mma_keep
  mmalu.io.ctrl.use_accum := false.B
  mmalu.io.ctrl.busy      := (dec.family === OpFamily.MMA)

  // MMALU write-back directly to VR (port 1) — NO precision truncation
  // mmalu.io.out is Vec(K, SInt(N4.W)) = Vec(K, SInt(32.W)) for N=8
  when (dec.family === OpFamily.MMA) {
    rf.io.vr_w_en(1)   := true.B
    rf.io.vr_w_addr(1) := io.mma_out_addr
    for (lane <- 0 until K) {
      rf.io.vr_w_data(1)(lane) := mmalu.io.out(lane).asUInt
    }
  }

  // ==========================================================================
  // VALU
  // ==========================================================================
  val valu = Module(new VALU(K, N))

  // Connect inputs from RF
  for (lane <- 0 until K) {
    valu.io.in_a_vx(lane) := rf.io.vx_r_data(1)(lane)
    valu.io.in_b_vx(lane) := rf.io.vx_r_data(2)(lane)
    valu.io.in_a_ve(lane) := rf.io.ve_r_data(0)(lane)
    valu.io.in_b_ve(lane) := rf.io.ve_r_data(1)(lane)
    valu.io.in_a_vr(lane) := rf.io.vr_r_data(0)(lane)
    valu.io.in_b_vr(lane) := rf.io.vr_r_data(1)(lane)
    valu.io.in_c_vr(lane) := rf.io.vr_r_data(1)(lane)  // C re-uses B port for now
  }

  // Drive VALU ctrl from decoded bundle
  valu.io.ctrl := dec.valu

  // Determine if this is a VALU family
  val isVALU = dec.family === OpFamily.VALU_ARITH  ||
               dec.family === OpFamily.VALU_LOGIC   ||
               dec.family === OpFamily.VALU_REDUCE  ||
               dec.family === OpFamily.VALU_LUT     ||
               dec.family === OpFamily.VALU_CVT     ||
               dec.family === OpFamily.VALU_BCAST   ||
               dec.family === OpFamily.VALU_FP      ||
               dec.family === OpFamily.VALU_FP_FMA  ||
               dec.family === OpFamily.VALU_MOV

  // VALU write-back (port 0 for each class)
  when (isVALU) {
    // VX write-back.
    // isReduceToVR ops (vsum, vrmax, vrmin) encode their *input* class in regCls
    // (e.g. vsum.vx has regCls=VX so the VALU selects the VX reduction path).
    // That would accidentally assert vx_w_en and clobber vx_out_addr — suppress it.
    // isSetLut ops (vsetlut) write only to VALU-internal bank registers;
    // all RF write ports must be suppressed.
    rf.io.vx_w_en(0)   := ((dec.valu.regCls === W.VX) || isNarrowCvtOut(dec.valu.op)) &&
                           !isReduceToVR(dec.valu.op) &&
                           !isSetLut(dec.valu.op)
    rf.io.vx_w_addr(0) := io.vx_out_addr
    for (lane <- 0 until K) rf.io.vx_w_data(0)(lane) := valu.io.out_vx(lane)

    // VE write-back
    rf.io.ve_w_en(0)   := dec.valu.regCls === W.VE
    rf.io.ve_w_addr(0) := io.ve_out_addr
    for (lane <- 0 until K) rf.io.ve_w_data(0)(lane) := valu.io.out_ve(lane)

    // VR write-back (FP/INT32, wide conversion results, and horizontal reductions).
    // vsetlut has regCls=VR but must NOT write the RF — suppress it.
    rf.io.vr_w_en(0)   := ((dec.valu.regCls === W.VR) || isWideCvtOut(dec.valu.op) ||
                            isReduceToVR(dec.valu.op)) &&
                           !isSetLut(dec.valu.op)
    rf.io.vr_w_addr(0) := io.vr_out_addr
    for (lane <- 0 until K) rf.io.vr_w_data(0)(lane) := valu.io.out_vr(lane)
  }

  // ==========================================================================
  // Helpers: determine output register class for conversion and reduce ops
  // ==========================================================================
  def isNarrowCvtOut(op: VecOp.Type): Bool = {
    op === VecOp.vcvt_s8_s32 ||  // s8 sign-extend → VX slice
    op === VecOp.vcvt_f32_s8     // FP32 → INT8 narrow
    // vcvt_s8_f32 = INT8→FP32: wide output → VR, NOT narrow
  }

  def isWideCvtOut(op: VecOp.Type): Bool = {
    op === VecOp.vcvt_s32_f32  ||  // s32→f32: wide
    op === VecOp.vcvt_s8_f32   ||  // s8→f32: wide
    op === VecOp.vcvt_f32_s32  ||
    op === VecOp.vcvt_s32_s8   ||
    op === VecOp.vcvt_f32_bf8  ||
    op === VecOp.vcvt_bf8_f32  ||
    op === VecOp.vcvt_f32_bf16 ||
    op === VecOp.vcvt_bf16_f32 ||
    op === VecOp.vcvt_s16_s32  ||
    op === VecOp.vcvt_s32_s16
  }

  /**
   * vsetlut writes only to VALU-internal LUT bank registers.
   * All register-file write ports must be suppressed for this op.
   */
  def isSetLut(op: VecOp.Type): Bool = op === VecOp.vsetlut

  /**
   * Horizontal reduce ops (vsum, vrmax, vrmin) always produce a VR-width result
   * broadcast across all K lanes, regardless of the regCls field in the instruction.
   * The VALU unconditionally drives out_vr for these ops; the backend must enable
   * the VR write port to store the result in the register file.
   *
   * Root cause: the ISA encodes reduce ops with the *input* register class in
   * funct7[1:0] (e.g. vsum.vx uses regCls=VX to select the VX reduction path),
   * but the output is always VR-width.  The backend's regCls===VR guard therefore
   * misses these ops when issued on VX or VE inputs.
   */
  def isReduceToVR(op: VecOp.Type): Bool = {
    op === VecOp.vsum  ||
    op === VecOp.vrmax ||
    op === VecOp.vrmin
  }
}

// See README.md for license details.
// -----------------------------------------------------------------------------
//  NpuAssembler.scala — Scala-side assembler for NPU instruction words
//
//  Produces 32-bit UInt literals that can be poked directly into
//  NeuralCoreMicroOp.word in simulation.
//
//  Usage example (in a spec):
//    import isa.NpuAssembler._
//    val instr = vadd(rd=0, rs1=1, rs2=2, width=VX)
//    dut.io.micro_op.word.poke(instr)
//
//  All methods return a Scala Int (bit pattern) that can be converted to
//  UInt via .U in a Chisel context, or wrapped by the asUInt helper.
// -----------------------------------------------------------------------------

package isa

import chisel3._

object NpuAssembler {

  // ---- Constants -----------------------------------------------------------

  // Width selectors (funct7[1:0])
  val VX = 0  // N(bits)-wide lanes
  val VE = 1  // 2N-wide lanes
  val VR = 2  // 4N-wide lanes

  // Rounding modes (funct7[3:2])
  val RNE   = 0
  val RTZ   = 1
  val FLOOR = 2
  val CEIL  = 3

  // Dtype class (funct7[6:5])
  val INT = 0
  val FP  = 1
  val BF  = 2

  // Format codes for vcvt (funct3 = dst, funct7[2:0] = src)
  val S8   = 0
  val S16  = 1
  val S32  = 2
  val F32  = 3
  val BF16 = 4
  val BF8  = 5   // BF8 variant (E4M3 vs E5M2) from bf8E5M2 parameter

  // ---- Encoding helpers ----------------------------------------------------

  /** Encode funct7 for R-type vector ops. */
  def f7(width: Int = VX, round: Int = RNE, sat: Boolean = false, dtype: Int = INT): Int =
    (width & 3) | ((round & 3) << 2) | ((if (sat) 1 else 0) << 4) | ((dtype & 3) << 5)

  /** Encode funct7 for VALU_CVT. */
  def f7Cvt(srcFmt: Int, sat: Boolean = true, round: Int = RNE, bf8E5M2: Boolean = false): Int =
    (srcFmt & 7) | ((if (sat) 1 else 0) << 3) | ((round & 3) << 4) | ((if (bf8E5M2) 1 else 0) << 6)

  /** Build R-type instruction word (returns Long to avoid signed-int overflow at bit 31). */
  def encR(opcode: Int, funct3: Int, funct7: Int, rd: Int, rs1: Int, rs2: Int): Int = {
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            ((rs2.toLong & 0x1F) << 20) |
            ((funct7.toLong & 0x7F) << 25)
    (w & 0xFFFFFFFFL).toInt  // keep 32 bits, return as (possibly signed) Int
  }

  /** Build I-type instruction word (imm is sign-extended 12-bit). */
  def encI(opcode: Int, funct3: Int, rd: Int, rs1: Int, imm: Int): Int = {
    val imm12 = imm.toLong & 0xFFF
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            (imm12 << 20)
    (w & 0xFFFFFFFFL).toInt
  }

  /** Build S-type (FMA) instruction word. rs3 at [31:27], rnd at [26:25]. */
  def encS(opcode: Int, funct3: Int, rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int = {
    val w = (opcode.toLong & 0x7F) |
            ((rd.toLong & 0x1F) << 7) |
            ((funct3.toLong & 0x7) << 12) |
            ((rs1.toLong & 0x1F) << 15) |
            ((rs2.toLong & 0x1F) << 20) |
            ((round.toLong & 0x3) << 25) |
            ((rs3.toLong & 0x1F) << 27)
    (w & 0xFFFFFFFFL).toInt
  }

  // ---- NOP / special -------------------------------------------------------

  val nop: Int = 0x00  // opcode=0x00, everything zero

  // ---- VALU_ARITH (opcode=0x10) --------------------------------------------

  def vadd (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 0, f7(width, sat=sat), rd, rs1, rs2)
  def vsub (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 1, f7(width, sat=sat), rd, rs1, rs2)
  def vmul (rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 2, f7(width, sat=sat), rd, rs1, rs2)
  def vneg (rd: Int, rs1: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 3, f7(width, sat=sat), rd, rs1, 0)
  def vabs (rd: Int, rs1: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 4, f7(width, sat=sat), rd, rs1, 0)
  def vmax (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int =
    encR(0x10, 5, f7(width), rd, rs1, rs2)
  def vmin (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int =
    encR(0x10, 6, f7(width), rd, rs1, rs2)
  def vrsub(rd: Int, rs1: Int, rs2: Int, width: Int = VX, sat: Boolean = false): Int =
    encR(0x10, 7, f7(width, sat=sat), rd, rs1, rs2)

  // ---- VALU_LOGIC (opcode=0x11) --------------------------------------------

  def vsll(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 0, f7(width), rd, rs1, rs2)
  def vsrl(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 1, f7(width), rd, rs1, rs2)
  def vsra(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 2, f7(width), rd, rs1, rs2)
  def vrol(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 3, f7(width), rd, rs1, rs2)
  def vxor(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int = encR(0x11, 4, f7(width), rd, rs1, rs2)
  def vnot(rd: Int, rs1: Int, width: Int = VX): Int            = encR(0x11, 5, f7(width), rd, rs1, 0)
  def vor (rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int  = encR(0x11, 6, f7(width), rd, rs1, rs2)
  def vand(rd: Int, rs1: Int, rs2: Int, width: Int = VX): Int  = encR(0x11, 7, f7(width), rd, rs1, rs2)

  // ---- VALU_REDUCE (opcode=0x12) -------------------------------------------

  def vsum (rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 0, f7(width), rd, rs1, 0)
  def vrmax(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 1, f7(width), rd, rs1, 0)
  def vrmin(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 2, f7(width), rd, rs1, 0)
  def vrand(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 3, f7(width), rd, rs1, 0)
  def vror (rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 4, f7(width), rd, rs1, 0)
  def vrxor(rd: Int, rs1: Int, width: Int = VX): Int = encR(0x12, 5, f7(width), rd, rs1, 0)

  // ---- VALU_LUT (opcode=0x13) — programmable two-bank LUT -------------------
  // Bank select: 0=A (default), 1=B.

  /**
   * Per-lane lookup: out[i] = lut_bank[in_a_vx[i]].
   * bank=0 → bank A (funct3=0), bank=1 → bank B (funct3=1).
   */
  def vlut(rd: Int, rs1: Int, bank: Int = 0): Int =
    encR(0x13, bank & 1, f7(VX), rd, rs1, 0)

  /**
   * Write one K×4-byte segment from VR[rs1] into the selected LUT bank.
   * segment: which K×4-entry block (0-based) within the 256-entry table.
   * bank=0 → bank A (funct3=4), bank=1 → bank B (funct3=5).
   * I-type: rd=0 (no register-file destination); imm=segment.
   */
  def vsetlut(rs1: Int, segment: Int, bank: Int = 0): Int =
    encI(0x13, 4 + (bank & 1), 0, rs1, segment)

  // ---- VALU_CVT (opcode=0x14) ----------------------------------------------
  // funct3 = dst fmt code; f7 encodes src + sat + round + bf8 variant

  def vcvt(rd: Int, rs1: Int,
           dstFmt: Int, srcFmt: Int,
           sat: Boolean = true, round: Int = RNE,
           bf8E5M2: Boolean = false): Int =
    encR(0x14, dstFmt, f7Cvt(srcFmt, sat, round, bf8E5M2), rd, rs1, 0)

  // Convenience aliases
  def vcvt_s8_s32 (rd: Int, rs1: Int, sat: Boolean = true,  round: Int = RNE): Int = vcvt(rd, rs1, S8,   S32, sat, round)
  def vcvt_s32_s8 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, S32, S8)
  def vcvt_s32_f32(rd: Int, rs1: Int, round: Int = RNE): Int = vcvt(rd, rs1, S32, F32, round=round)
  def vcvt_f32_s32(rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, S32, sat=false)
  def vcvt_f32_s8 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, S8,  sat=false)
  def vcvt_s8_f32 (rd: Int, rs1: Int, sat: Boolean = true, round: Int = RNE): Int = vcvt(rd, rs1, S8,   F32, sat, round)
  def vcvt_f32_bf16(rd: Int, rs1: Int): Int = vcvt(rd, rs1, F32, BF16, sat=false)
  def vcvt_bf16_f32(rd: Int, rs1: Int): Int = vcvt(rd, rs1, BF16, F32, sat=false)
  def vcvt_f32_bf8 (rd: Int, rs1: Int, e5m2: Boolean = false): Int = vcvt(rd, rs1, F32, BF8, sat=false, bf8E5M2=e5m2)
  def vcvt_bf8_f32 (rd: Int, rs1: Int, e5m2: Boolean = false): Int = vcvt(rd, rs1, BF8, F32, sat=false, bf8E5M2=e5m2)
  def vcvt_s16_s32 (rd: Int, rs1: Int, sat: Boolean = true): Int   = vcvt(rd, rs1, S16, S32, sat)
  def vcvt_s32_s16 (rd: Int, rs1: Int): Int = vcvt(rd, rs1, S32, S16, sat=false)

  // ---- VALU_BCAST (opcode=0x15) --------------------------------------------

  /** Broadcast lane 0 of rs1 to all K lanes of rd (R-format). */
  def vbcast(rd: Int, rs1: Int, width: Int = VX): Int =
    encR(0x15, 0, f7(width), rd, rs1, 0)

  /** Broadcast sign-extended 12-bit immediate to all K lanes of rd (I-format). */
  def vbcastImm(rd: Int, imm: Int, width: Int = VX): Int =
    encI(0x15, 1, rd, 0, imm)

  // ---- VALU_FP (opcode=0x16) — FP32 on VR ---------------------------------

  def vfadd(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 0, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfsub(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 1, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfmul(rd: Int, rs1: Int, rs2: Int, round: Int = RNE): Int =
    encR(0x16, 2, f7(VR, round=round, dtype=FP), rd, rs1, rs2)
  def vfneg(rd: Int, rs1: Int): Int =
    encR(0x16, 3, f7(VR, dtype=FP), rd, rs1, 0)
  def vfabs(rd: Int, rs1: Int): Int =
    encR(0x16, 4, f7(VR, dtype=FP), rd, rs1, 0)
  def vfmax(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x16, 5, f7(VR, dtype=FP), rd, rs1, rs2)
  def vfmin(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x16, 6, f7(VR, dtype=FP), rd, rs1, rs2)

  // ---- VALU_FP_FMA (opcode=0x17) — S-format -------------------------------

  def vfma (rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 0, rd, rs1, rs2, rs3, round)
  def vfms (rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 1, rd, rs1, rs2, rs3, round)
  def vnfma(rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 2, rd, rs1, rs2, rs3, round)
  def vnfms(rd: Int, rs1: Int, rs2: Int, rs3: Int, round: Int = RNE): Int =
    encS(0x17, 3, rd, rs1, rs2, rs3, round)

  // ---- VALU_MOV (opcode=0x18) ----------------------------------------------

  def vmov (rd: Int, rs1: Int, width: Int = VX): Int =
    encR(0x18, 0, f7(width), rd, rs1, 0)
  def vmovi(rd: Int, imm: Int, width: Int = VX): Int =
    encI(0x18, 1, rd, 0, imm)
  def vmovh(rd: Int, imm: Int): Int =
    encI(0x18, 2, rd, 0, imm)

  // ---- MMA (opcode=0x03) ---------------------------------------------------

  /** mma rd=outVR, rs1=A_VX_base, rs2=B_VX_base; keep in funct7[4] (sat bit). */
  def mma(rd: Int, rs1: Int, rs2: Int, keep: Boolean = true): Int =
    encR(0x03, 0, f7(VR, sat=keep), rd, rs1, rs2)
  def mmaLast(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x03, 1, f7(VR), rd, rs1, rs2)
  def mmaReset(rd: Int, rs1: Int, rs2: Int): Int =
    encR(0x03, 2, f7(VR), rd, rs1, rs2)

  // ---- LD / ST (opcodes 0x01 / 0x02) --------------------------------------

  def ldVx(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 3, rd, base, offset)
  def ldVe(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 4, rd, base, offset)
  def ldVr(rd: Int, base: Int, offset: Int = 0): Int = encI(0x01, 5, rd, base, offset)
  def stVx(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 3, 0, base, offset)
  def stVe(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 4, 0, base, offset)
  def stVr(rs2: Int, base: Int, offset: Int = 0): Int = encI(0x02, 5, 0, base, offset)

  // ---- Convenience: convert Scala Int to Chisel UInt -----------------------
  implicit class IntToUInt(val v: Int) {
    // Convert to UInt treating the int as an unsigned 32-bit bit pattern
    def asUInt: chisel3.UInt = (v.toLong & 0xFFFFFFFFL).U(32.W)
  }
}
